35	// This bean is added to handle injection on the ObserverMethod as it does not work on an Extension class.
36	@Singleton
37	public class OciMetricsBean {
38	
39	    // Make Priority higher than MetricsCdiExtension so this will only start after MetricsCdiExtension has completed.
40	    void registerOciMetrics(@Observes @Priority(LIBRARY_BEFORE + 20) @Initialized(ApplicationScoped.class) Object ignore,
41	                            Config config, Monitoring monitoringClient) {
42	        Config ocimetrics = config.get("ocimetrics");
43	        OciMetricsSupport.Builder builder = OciMetricsSupport.builder()
44	                .config(ocimetrics)
45	                .monitoringClient(monitoringClient);
46	        if (builder.enabled()) {
47	            activateOciMetricsSupport(ocimetrics, builder);
48	        }
49	    }
50	
51	    void activateOciMetricsSupport(Config ocimetrics, OciMetricsSupport.Builder builder) {
52	        RoutingBuilders.create(ocimetrics)
53	                .routingBuilder()
54	                .register(builder.build());
55	    }
56	}
