105	    public interface NameFormatter {
106	
107	        /**
108	         * Formats a metric name for OCI.
109	         * <p>
110	         *     The default implementation creates an OCI metric name with this format:
111	         *     {@code metric-name[_suffix][_units]}
112	         *     where {@code _suffix} is omitted if the caller passes a null suffix, and {@code _units} is omitted if the metrics
113	         *     metadata does not have units set or, in translating the units for OCI, the result is blank.
114	         * </p>
115	         *
116	         * @param metric the metric to be formatted
117	         * @param metricId {@code MetricID} of the metric being formatted
118	         * @param suffix name suffix to append to the recorded metric name (e.g, "total"); can be null
119	         * @param unit metric unit
120	         * @return the formatted metric name
121	         */
122	        default String format(Meter metric, Meter.Id metricId, String suffix, String unit) {
123	
124	            StringBuilder result = new StringBuilder(metricId.name());
125	            if (suffix != null) {
126	                result.append("_").append(suffix);
127	            }
128	            result.append("_").append(textType(metric).replace(" ", "_"));
129	
130	            String units = formattedBaseUnits(unit);
131	            if (units != null && !units.isBlank()) {
132	                result.append("_").append(units);
133	            }
134	            return result.toString();
135	        }
136	
137	        /**
138	         * Converts a metric instance into the corresponding text representation of its metric type.
139	         *
140	         * @param metric {@link io.helidon.metrics.api.Meter} to be converted
141	         * @return text type of the metric
142	         */
143	        static String textType(Meter metric) {
144	            if (metric instanceof Counter) {
145	                return "counter";
146	            }
147	            if (metric instanceof FunctionalCounter) {
148	                return "counter";
149	            }
150	            if (metric instanceof Gauge) {
151	                return "gauge";
152	            }
153	            if (metric instanceof DistributionSummary) {
154	                return "histogram";
155	            }
156	            if (metric instanceof Timer) {
157	                return "timer";
158	            }
159	            throw new IllegalArgumentException("Cannot map metric of type " + metric.getClass().getName());
160	        }
161	    }
162	
163	    static String formattedBaseUnits(String metricUnits) {
164	        String baseUnits = baseMetricUnits(metricUnits);
165	        return baseUnits == null ? "" : baseUnits;
166	    }
