 *     configured and activated. Subclasses can override {@link #configKey()} to change the config key used to look up the
 *     OCI metrics settings and {@link #ociMetricsSupportBuilder(Config, Config, Monitoring)} to customize how the
 *     {@link OciMetricsSupport.Builder} is initialized.
 * </p>
 */

// This bean is added to handle injection on the ObserverMethod as it does not work on an Extension class.
@Singleton
public class OciMetricsBean {

    private OciMetricsSupport ociMetricsSupport;

    /**
     * Returns the config key used to look up the OCI metrics settings from the root config.
     * <p>
     *     Defaults to {@code "ocimetrics"}. Subclasses can override this to use a different config key.
     * </p>
     *
     * @return the config key for the OCI metrics settings
     */
    protected String configKey() {
        return "ocimetrics";
    }

    /**
     * Returns an {@link OciMetricsSupport.Builder} initialized using the provided config and monitoring client.
     * <p>
     *     Subclasses can override this to further customize the builder.
     * </p>
     *
     * @param rootConfig the root {@link Config}
     * @param ociMetricsConfig the OCI metrics {@link Config} node
     * @param monitoring the {@link Monitoring} client to use for sending metrics to OCI
     * @return the initialized builder
     */
    protected OciMetricsSupport.Builder ociMetricsSupportBuilder(Config rootConfig,
                                                                 Config ociMetricsConfig,
                                                                 Monitoring monitoring) {
        return OciMetricsSupport.builder()
                .config(ociMetricsConfig)
                .monitoringClient(monitoring);
    }

    /**
     * Builds and stores the {@link OciMetricsSupport} instance from the provided builder and registers it with the
     * routing builder derived from the OCI metrics config node.
     *
     * @param rootConfig the root {@link Config}
     * @param ociMetricsConfig the OCI metrics {@link Config} node
     * @param builder the builder used to create the {@link OciMetricsSupport} instance
     */
    protected void activateOciMetricsSupport(Config rootConfig, Config ociMetricsConfig, OciMetricsSupport.Builder builder) {
        ociMetricsSupport = builder.build();
        RoutingBuilders.create(ociMetricsConfig)
                .routingBuilder()
                .register(ociMetricsSupport);
    }

    /**
     * Returns the {@link OciMetricsSupport} instance created during activation.
     *
     * @return the {@code OciMetricsSupport} instance, or {@code null} if it has not been activated
     */
    OciMetricsSupport ociMetricsSupport() {
        return ociMetricsSupport;
    }

    // Make Priority higher than MetricsCdiExtension so this will only start after MetricsCdiExtension has completed.
    void registerOciMetrics(@Observes @Priority(LIBRARY_BEFORE + 20) @Initialized(ApplicationScoped.class) Object ignore,
                            Config rootConfig, Monitoring monitoringClient) {
        Config ociMetricsConfig = rootConfig.get(configKey());
        OciMetricsSupport.Builder builder = ociMetricsSupportBuilder(rootConfig, ociMetricsConfig, monitoringClient);
        if (builder.enabled()) {
            activateOciMetricsSupport(rootConfig, ociMetricsConfig, builder);
        }
    }
}
